window.guideResponse=function(input){
 const q=input.toLowerCase().trim(),items=picks(),last=state.activity[0];
 if(/\b(next|what should i learn|weak|struggle|learn next|my path|my goals)\b|अगला|क्या सीख/.test(q)){return E('Based on your selected goal and learning evidence, your next step is: ','आपका अगला कदम: ')+(items[0]?`${titleOf(items[0])}. ${items[0].reason}`:'Choose a new learning goal in Accessibility & goals.');}
 if(/\b(my mistake|wrong answer|i got wrong|why did i fail|my gap)\b|गलती/.test(q)){
 const mistake=Object.entries(state.misconceptions).sort((a,b)=>b[1]-a[1])[0];return mistake?`Your most frequently missed topic is ${textFor(modules.find(m=>m.id===mistake[0]))}. Open the corresponding lesson and try the associated short practice game. The learning path adapts as you improve.`:'No repeated misconception has yet been observed. You can take a diagnostic or play a relevant learning game.';
 }
 if(/\b(what am i learning|current topic|current lesson|what does this mean)\b/.test(q)&&page==='lesson')return c(modules.find(m=>m.id===activeLesson)).intro;
 return original.guideResponse(input);
};
